orbitFallback.instrumentationSource:
(async () => {
  const { engine, planet, walker } = window.__nmsEditorDebug
  const expectedDraws = engine.renderer.info.render.calls
  if (walker.isEnabled() || expectedDraws !== 43) throw new Error('Not the settled orbit pose')
  window.__orbitFallbackPairs = []
  const { default: original } = await import('/scripts/far-band-variants.js?raw')
  const replacements = [
    ["  if (!walker?.isEnabled?.()) throw new Error('walker caiu -- rode prepare() de novo')", "  if (walker?.isEnabled?.()) throw new Error('Not in orbit')"],
    ['  const mats = planet.farLodMaterials', '  const mats = [planet.fallbackMaterial]'],
    ['        diffs.push(base - cut)', `        diffs.push(base - cut)
        if (window.__nmsEditorDebug.planet !== window.__orbitFallbackPlanet || walker.isEnabled() || engine.renderer.info.render.calls !== 43 || engine.getPixelRatioLimit() !== 1) throw new Error('Orbit scene changed')
        window.__orbitFallbackPairs.push({ key, repeat: r, variantFirst: r % 2 === 0, baseMs: base, revertedMs: cut, draws: engine.renderer.info.render.calls, triangles: engine.renderer.info.render.triangles })`],
    ['draws.every(x => x > 300 && Math.abs(x - draws[0]) <= 4)', 'draws.every(x => x === 43)'],
  ]
  let source = original
  for (const [anchor, replacement] of replacements) {
    if (source.split(anchor).length !== 2) throw new Error('Anchor missing or ambiguous: ' + anchor)
    source = source.replace(anchor, replacement)
  }
  window.__orbitFallbackPlanet = planet
  const url = URL.createObjectURL(new Blob([source], { type: 'text/javascript' }))
  try {
    const module = await import(url)
    const measurement = await module.priceVariants({ keys: ['control', 'revertBoth'], repeats: 6, frames: 180, recompileMs: 2200 })
    return { materialScope: 'fallbackMaterial only; this is the visible orbital terrain', measurement, pairs: window.__orbitFallbackPairs }
  } finally { URL.revokeObjectURL(url) }
})()
